import type { FactionId, UnitType } from '../../game/types';

/**
 * Maps `${faction}_${unitType}` -> unified Polytopia-style flat-shaded SVG sprite URL.
 * All 24 faction × unit sprites are 512×512 bottom-anchored (y = 492) vector assets
 * generated by `scripts/generate_polytopia_sprites.mjs`.
 */
export const UNIT_SPRITE_URLS: Record<string, string> = {
  // Humans (Gondor & Rohan) — 6 unified Polytopia SVGs
  humans_warrior: '/sprites/humans_warrior.svg',
  humans_defender: '/sprites/humans_defender.svg',
  humans_archer: '/sprites/humans_archer.svg',
  humans_rider: '/sprites/humans_rider.svg',
  humans_catapult: '/sprites/humans_catapult.svg',
  humans_rohirrim_knight: '/sprites/humans_rohirrim_knight.svg',

  // Orcs (Mordor & Isengard) — 6 unified Polytopia SVGs
  orcs_warrior: '/sprites/orcs_warrior.svg',
  orcs_defender: '/sprites/orcs_defender.svg',
  orcs_archer: '/sprites/orcs_archer.svg',
  orcs_rider: '/sprites/orcs_rider.svg',
  orcs_catapult: '/sprites/orcs_catapult.svg',
  orcs_uruk_berserker: '/sprites/orcs_uruk_berserker.svg',

  // Elves (Lothlórien & Rivendell) — 6 unified Polytopia SVGs
  elves_warrior: '/sprites/elves_warrior.svg',
  elves_defender: '/sprites/elves_defender.svg',
  elves_archer: '/sprites/elves_archer.svg',
  elves_rider: '/sprites/elves_rider.svg',
  elves_catapult: '/sprites/elves_catapult.svg',
  elves_elven_sentinel: '/sprites/elves_elven_sentinel.svg',

  // Dwarves (Erebor & Khazad-dûm) — 6 unified Polytopia SVGs
  dwarves_warrior: '/sprites/dwarves_warrior.svg',
  dwarves_defender: '/sprites/dwarves_defender.svg',
  dwarves_archer: '/sprites/dwarves_archer.svg',
  dwarves_rider: '/sprites/dwarves_rider.svg',
  dwarves_catapult: '/sprites/dwarves_catapult.svg',
  dwarves_ironbreaker: '/sprites/dwarves_ironbreaker.svg',
};

const UNIQUE_UNIT_FALLBACKS: Partial<Record<UnitType, string>> = {
  rohirrim_knight: UNIT_SPRITE_URLS.humans_rohirrim_knight,
  uruk_berserker: UNIT_SPRITE_URLS.orcs_uruk_berserker,
  elven_sentinel: UNIT_SPRITE_URLS.elves_elven_sentinel,
  ironbreaker: UNIT_SPRITE_URLS.dwarves_ironbreaker,
};

export function getUnitSpriteUrl(unitType: UnitType, faction: FactionId): string {
  const key = `${faction}_${unitType}`;
  const exact = UNIT_SPRITE_URLS[key];
  if (exact) return exact;

  const uniqueFallback = UNIQUE_UNIT_FALLBACKS[unitType];
  if (uniqueFallback) return uniqueFallback;

  return UNIT_SPRITE_URLS[`${faction}_warrior`] ?? UNIT_SPRITE_URLS.humans_warrior;
}
